mapper.update:
UPDATE public_image_quota
SET used_file_count = used_file_count + 1,
    used_bytes = used_bytes + #{fileSize},
    updated_at = CURRENT_TIMESTAMP
WHERE owner_user_id = #{ownerUserId}
  AND used_file_count < #{maxFiles}
  AND #{fileSize} <= #{maxBytes}
  AND used_bytes <= #{maxBytes} - #{fileSize}

mapper.select:
SELECT asset_id, relative_path, owner_user_id, file_size
FROM public_image_asset
WHERE relative_path = #{relativePath}

mapper.update:
UPDATE public_image_asset
SET relative_path = #{relativePath}
WHERE asset_id = #{assetId}
